<?php get_header(); while (have_posts()) : the_post(); ?>
<main id="main" class="single-journal"><header class="journal-hero site-shell"><p class="eyebrow"><?php echo esc_html(get_the_date('d F Y')); ?> · <?php echo esc_html(get_the_author()); ?></p><h1><?php the_title(); ?></h1><p class="journal-deck"><?php echo esc_html(get_the_excerpt()); ?></p></header><?php if (has_post_thumbnail()) : ?><figure class="journal-cover image-reveal"><?php the_post_thumbnail('full'); ?></figure><?php endif; ?><article class="entry-content journal-content"><?php the_content(); ?></article><nav class="site-shell project-nav"><?php previous_post_link('%link', '← %title'); next_post_link('%link', '%title →'); ?></nav></main>
<?php endwhile; get_footer(); ?>
